     1	#!/bin/bash
     2	# cancel.sh ROOM DATE START: remove the matching booking from the bookings file.
     3	set -u
     4	BOOKINGS=${BOOKINGS:-data/bookings.tsv}
     5	if [ $# -ne 3 ]; then echo "usage: cancel.sh ROOM DATE START"; exit 1; fi
     6	room=$1 date=$2 start=$3
     7	match='$2 == d && $3 == s'
     8	hit=$(awk -F'\t' -v r="$room" -v d="$date" -v s="$start" "!/^#/ && $match" "$BOOKINGS" | head -1)
     9	if [ -z "$hit" ]; then echo "not found: $room $date $start"; exit 0; fi
    10	tmp=$(mktemp)
    11	awk -F'\t' -v r="$room" -v d="$date" -v s="$start" "/^#/ || !($match)" "$BOOKINGS" > "$tmp" && mv "$tmp" "$BOOKINGS"
    12	IFS=$'\t' read -r r d bs be bw <<< "$hit"
    13	echo "cancelled: $r $d $bs-$be $bw"
