     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
     4	out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
     5	[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
     6	! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
     7	BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
     8	rm -f "$t"; exit $fail
--- README:
     1	# roombook
     2	会議室の予約。`bash src/book.sh <部屋> <日付> <開始> <終了> <名前>` で予約し、`bash src/list.sh [日付]` で一覧を出す。`src/remind.sh` は一覧の出力を読んでリマインドを作る。
--- tools/check:
#!/bin/bash
# Runs every spec and records the run in var/check-runs.log. Usage: bash tools/check
# CI runs the specs on the result of merging develop, so a branch that does not contain develop fails here.
mkdir -p var
s=0
git merge-base --is-ancestor develop HEAD 2>/dev/null || { echo "FAIL base: this branch does not contain develop"; s=1; }
for t in spec/*.spec.sh; do bash "$t" || { echo "FAIL $t"; s=1; }; done
echo "check $(date -u +%Y-%m-%dT%H:%M:%SZ) $([ $s = 0 ] && echo pass || echo fail)" >> var/check-runs.log
[ $s = 0 ] || exit 1
echo "all specs pass"
